# ---- Claude Code update check (native install) ----
check_cc_update() {
  local current_version="$1"
  local cache_file="$HOME/.claude/.cc_version_cache"

  # Return empty if no current version
  [ -z "$current_version" ] && return

  # If cache exists and fresh (< 24h), use it
  if [ -f "$cache_file" ]; then
    local cache_age=$(( $(date +%s) - $(stat -f %m "$cache_file" 2>/dev/null || echo 0) ))
    if [ "$cache_age" -lt 86400 ]; then
      local cached_latest=$(cat "$cache_file" 2>/dev/null)
      if [ -n "$cached_latest" ] && [ "$cached_latest" != "$current_version" ]; then
        echo "⬆️ $cached_latest"
      fi
      return
    fi
  fi

  # Check latest version via claude --version (background, non-blocking)
  (
    latest_version=$(claude --version 2>/dev/null | head -1 | sed 's/ .*//')
    if [ -n "$latest_version" ]; then
      echo "$latest_version" > "$cache_file" 2>/dev/null
    fi
  ) &
}

# ---- language version detection ----
lang_version=""
lang_icon=""

# Get actual directory path (resolve ~)
real_dir=$(echo "$current_dir" | sed "s|~|$HOME|g")

# Check for Node.js project
if [ -f "${real_dir}/package.json" ]; then
  if command -v node >/dev/null 2>&1; then
    node_version=$(node --version 2>/dev/null | sed 's/v//')
    if [ -n "$node_version" ]; then
      lang_version="$node_version"
      lang_icon="⬢"  # Node.js hexagon
    fi
  fi
# Check for Python project
elif [ -f "${real_dir}/pyproject.toml" ] || [ -f "${real_dir}/requirements.txt" ]; then
  if command -v python3 >/dev/null 2>&1; then
    python_version=$(python3 --version 2>/dev/null | awk '{print $2}')
    if [ -n "$python_version" ]; then
      lang_version="$python_version"
      lang_icon="🐍"  # Python snake
    fi
  elif command -v python >/dev/null 2>&1; then
    python_version=$(python --version 2>/dev/null | awk '{print $2}')
    if [ -n "$python_version" ]; then
      lang_version="$python_version"
      lang_icon="🐍"  # Python snake
    fi
  fi
fi

# ---- render statusline ----
# Line 1: Core info (directory, git, model, claude code version, output style)
printf '📁 %s%s%s' "$(dir_color)" "$current_dir" "$(rst)"
if [ -n "$git_branch" ]; then
  printf '  🌿 %s%s%s' "$(git_color)" "$git_branch" "$(rst)"
fi
# Add language version after git branch
if [ -n "$lang_version" ]; then
  printf '  %s %s%s%s' "$lang_icon" "$(version_color)" "$lang_version" "$(rst)"
fi
printf '  🤖 %s%s%s' "$(model_color)" "$model_name" "$(rst)"
if [ -n "$model_version" ] && [ "$model_version" != "null" ]; then
  printf '  🏷️ %s%s%s' "$(version_color)" "$model_version" "$(rst)"
fi
if [ -n "$cc_version" ] && [ "$cc_version" != "null" ]; then
  update_indicator=$(check_cc_update "$cc_version")
  if [ -n "$update_indicator" ]; then
    printf '  📟 %sv%s %s%s' "$(cc_version_color)" "$cc_version" "$update_indicator" "$(rst)"
  else
    printf '  📟 %sv%s%s' "$(cc_version_color)" "$cc_version" "$(rst)"
  fi
fi
# Vim mode
if [ -n "$vim_mode" ] && [ "$vim_mode" != "null" ]; then
  if [ "$vim_mode" = "NORMAL" ]; then
    printf '  %s[N]%s' "$(vim_color)" "$(rst)"
  elif [ "$vim_mode" = "INSERT" ]; then
    printf '  %s[I]%s' "$(vim_color)" "$(rst)"
  else
    printf '  %s[%s]%s' "$(vim_color)" "$vim_mode" "$(rst)"
  fi
fi
# Agent name
if [ -n "$agent_name" ] && [ "$agent_name" != "null" ]; then
  printf '  🕵️ %s%s%s' "$(agent_color)" "$agent_name" "$(rst)"
fi
# Lines changed (additions/deletions)
if [ -n "$lines_added" ] || [ -n "$lines_removed" ]; then
  printf '  📝 %s+%s%s/%s-%s%s' "$(lines_add_color)" "${lines_added:-0}" "$(rst)" "$(lines_del_color)" "${lines_removed:-0}" "$(rst)"
fi

# Line 2: Context only
line2=""
if [ -n "$context_pct" ]; then
  # Context temperature indicator
  if [ "$context_remaining_pct" -le 20 ]; then
    temp_emoji="🔴"
    compact_warn="  ⚠️ $(warning_color)COMPACT SOON$(rst)"
  elif [ "$context_remaining_pct" -le 40 ]; then
    temp_emoji="🟡"
    compact_warn=""
  else
    temp_emoji="🟢"
    compact_warn=""
  fi
  # 80%+ used (remaining ≤20%) → compact warning
  ctx_used_int=$(( 100 - context_remaining_pct ))
  if [ "$ctx_used_int" -ge 80 ]; then
    compact_warn="  ⚠️ $(warning_color)COMPACT SOON (${ctx_used_int}% used)$(rst)"
  fi
  if [ -n "$context_detail" ]; then
    line2="${temp_emoji} 🧠 $(context_color)Context: ${context_detail} (${context_pct} remaining)$(rst)${compact_warn}"
  else
    line2="${temp_emoji} 🧠 $(context_color)Context Remaining: ${context_pct}$(rst)${compact_warn}"
  fi
fi
# DELETED: Token usage breakdown (input/output/cache) removed per user request
# DELETED: Session ID removed per user request
# DELETED: 200K token warning removed per user request
# DELETED: Session time removed per user request
if [ -z "$line2" ] && [ -z "$context_pct" ]; then
  line2="🧠 $(context_color)Context Remaining: TBD$(rst)"
fi

# Line 3: DELETED - Token usage, cost, and TODO tracking section removed per user request

# Line 4: Transcript path (OSC 8 clickable link)
line4=""
if [ -n "$transcript_path" ] && [ "$transcript_path" != "null" ] && [ "$transcript_path" != "" ]; then
  # Shorten path for display
  short_transcript=$(echo "$transcript_path" | sed "s|^$HOME|~|g")
  # OSC 8 hyperlink: \e]8;;URL\aTEXT\e]8;;\a
  line4="📜 $(link_color)\033]8;;file://${transcript_path}\a${short_transcript}\033]8;;\a$(rst)"
fi

# Print lines
if [ -n "$line4" ]; then
  printf '\n'"$line4"
fi
if [ -n "$line2" ]; then
  printf '\n%s' "$line2"
fi
printf '\n'
